import fs from 'node:fs';import assert from 'node:assert/strict';import {test} from 'node:test';
test('explicit archive/ROM/mapper/UI failures are short English codes',()=>{const root=new URL('../source/',import.meta.url);let count=0;for(const name of ['archive.js','rom.js','mappers.js']){const s=fs.readFileSync(new URL(name,root),'utf8');for(const m of s.matchAll(/(?:archiveCheck\([^;\n]*?,|reason=|throw (?:new )?Error\()'([^']+)'/g)){assert.match(m[1],/^[A-Za-z0-9]{1,6}$/);count++;}}assert.ok(count>10);const ui=fs.readFileSync(new URL('ui.js',root),'utf8');assert.ok(ui.includes('/^[A-Za-z0-9]{1,6}$/'));assert.ok(ui.includes("'Full'"));assert.ok(ui.includes("'Fail'"));});
